\ollabel{thm:strong-generalization} If $c$ is a constant not occurring
in $\Gamma$ or $!A(x)$ and $\Gamma \Proves !A(c)$, then $\Gamma
\Proves \lforall[x][!A(x)]$.
\end{thm}

